dFields(CStream_AC* aStream);		virtual void WriteFields(CStream_AC* aStream) const;	//------------------------------------------------------------------------------------	// Data member accessors.	//------------------------------------------------------------------------------------	virtual void ReleasePicture();		// Releases the PICT by disposing of fDataHandle.	virtual void SetPicture(PicHandle thePicture, bool redraw);		// Sets fDataHandle to thePicture, redrawing if redraw is true.	virtual void SetPictureRsrcID(ResNumber itsRsrcID, bool redraw);		// setter for fRsrcID	//------------------------------------------------------------------------------------	// Imaging.	//------------------------------------------------------------------------------------	virtual void Draw(const CViewRect& area);		// Responsible for drawing the PICT and any required adornments.			//------------------------------------------------------------------------------------	// Drag & Drop	//------------------------------------------------------------------------------------#if qDrag		virtual bool WillDrag(const CViewPoint& theMouse, const RgnHandle dragCursorRegion);		// return true if picture content exists, and the view is draggable	virtual void DoAddDragContent();		// Install PICT flavor data as a promise	virtual bool WillAcceptDrop(CDragItemIterator& dragItemIterator);		// return true if drag is a single item available as a 'PICT'			virtual TCommand* DoMakeDragDropCommand(CommandNumber 		itsCommandNumber,											CDragItemIterator&	dragItemIterator,											TDragTracker*		targetTracker = NULL);		// Create and return a command that will be posted by the drag session.		virtual void DoFulfillPromise(TDragItem* promisedItem);		// Provide promised data on demand.		#endif // qDrag	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	PicHandle fDataHandle;	ResNumber fRsrcID;};//----------------------------------------------------------------------------------------// TPictureCommand: Command that manages inserting and removing data from a TPicture.//----------------------------------------------------------------------------------------class EXPORT_MA TPictureCommand : public TCommand// The TPictureCommand class is used during a drag and drop operation// to copy picture data from the drag source to the drag destination.//    This class is reserved for internal use by MacApp. Do not// call or override its methods.{public:	TPictureCommand(ResNumber newRsrcID = kNoResource,					PicHandle newPicHandle = NULL,					TPicture* itsPictureView = NULL,					CommandNumber itsCommandNumber = cNoCommand,					TEventHandler* itsContext = NULL,					bool canUndo = true,					bool causesChange = true,					MDependable_AC* objectToNotify = NULL);		// Constructor			virtual ~TPictureCommand();		virtual void DoIt();		virtual void UndoIt();	virtual Size TotalSize(bool justLocked) const;	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------protected:	TPicture*	fPictureView;	PicHandle	fSavedDataHandle;	ResNumber	fSavedRsrcID;};EXPORT_MA void InitUPicture();#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.			04/17/96	InitUPicture		04/15/96	moved MDependable_AC from TObject		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/